 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Transação Alto Valor', 'amount > 50000', 'block', true, '[{"field": "amount", "value": "50000", "operator": ">"}]'::jsonb, 'AND', 1, NULL, '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DOUBLE_CHECK_TEST', 'amount > 99999', 'block', true, '[{"field": "amount", "value": "99999", "operator": ">"}]'::jsonb, 'AND', 1, NULL, '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX Alto Valor Noturno', 'channel == PIX AND amount > 10000 AND hour >= 0 AND hour <= 6', 'block', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "10000", "operator": ">"}, {"field": "hour", "value": "0", "operator": ">="}, {"field": "hour", "value": "6", "operator": "<="}]'::jsonb, 'AND', 1, 'Bloqueia PIX acima de 10k entre meia-noite e 6h', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX Horário Crítico 13h', 'channel == PIX AND hour >= 12 AND hour <= 14', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "hour", "value": "12", "operator": ">="}, {"field": "hour", "value": "14", "operator": "<="}]'::jsonb, 'AND', 1, 'SITUAÇÃO HIPOTÉTICA: Maria, funcionária de uma empresa, recebe um SMS às 13h10 informando que sua conta será bloqueada. Nervosa, ela clica no link e faz um PIX de R$ 2.000 para regularizar. A regra de', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX Valor Crítico R$5.000-10.000', 'channel == PIX AND amount >= 5000 AND amount <= 10000', 'block', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "5000", "operator": ">="}, {"field": "amount", "value": "10000", "operator": "<="}]'::jsonb, 'AND', 2, 'SITUAÇÃO HIPOTÉTICA: João, idoso de 72 anos, recebe ligação de "banco" pedindo atualização cadastral. O golpista convence João a fazer PIX de R$ 7.500 para "conta segura". A regra bloqueia: faixa R$5k', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX Madrugada Bloqueio', 'channel == PIX AND hour >= 0 AND hour <= 5', 'block', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "hour", "value": "0", "operator": ">="}, {"field": "hour", "value": "5", "operator": "<="}]'::jsonb, 'AND', 3, 'SITUAÇÃO HIPOTÉTICA: Pedro teve o celular roubado às 2h após sair de festa. Os criminosos tentam fazer PIX às 3h30. A regra bloqueia imediatamente: transações PIX de madrugada têm altíssimo risco.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Mobile Alto Valor Noturno', 'channel == mobile AND amount > 3000 AND hour >= 20', 'review', true, '[{"field": "channel", "value": "mobile", "operator": "=="}, {"field": "amount", "value": "3000", "operator": ">"}, {"field": "hour", "value": "20", "operator": ">="}]'::jsonb, 'AND', 4, 'SITUAÇÃO HIPOTÉTICA: Ana baixou app falso de banco às 21h. O malware captura suas credenciais e tenta transferir R$ 5.000. A regra intercepta: mobile + noturno + alto valor = 83% fraude.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Primeira Transação Alto Valor PIX', 'is_first_transaction == true AND channel == PIX AND amount > 2000', 'review', true, '[{"field": "is_first_transaction", "value": "true", "operator": "=="}, {"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "2000", "operator": ">"}]'::jsonb, 'AND', 5, 'SITUAÇÃO HIPOTÉTICA: Conta recém-aberta com dados falsos tenta fazer PIX de R$ 3.500. A regra detecta: primeira transação + PIX + valor alto = padrão de conta laranja.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Velocidade Alta - Ataque Automatizado', 'velocity_1h > 5 AND amount > 1000', 'block', true, '[{"field": "velocity_1h", "value": "5", "operator": ">"}, {"field": "amount", "value": "1000", "operator": ">"}]'::jsonb, 'AND', 6, 'SITUAÇÃO HIPOTÉTICA: Criminoso com bot automatizado tenta fazer 10 PIX de R$ 1.500 em 30 minutos usando credenciais roubadas. A regra bloqueia: mais de 5 transações/hora = ataque de força bruta.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Novo Dispositivo + Alto Valor', 'is_new_device == true AND amount > 5000', 'step_up', true, '[{"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "amount", "value": "5000", "operator": ">"}]'::jsonb, 'AND', 7, 'SITUAÇÃO HIPOTÉTICA: Carlos perde o celular. Criminoso acessa conta de novo dispositivo e tenta transferir R$ 8.000. A regra exige autenticação extra: novo aparelho = risco elevado.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX Valor Suspeito R$100-500', 'channel == PIX AND amount >= 100 AND amount <= 500 AND velocity_24h > 3', 'alert', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "100", "operator": ">="}, {"field": "amount", "value": "500", "operator": "<="}, {"field": "velocity_24h", "value": "3", "operator": ">"}]'::jsonb, 'AND', 8, 'SITUAÇÃO HIPOTÉTICA: Golpista usa conta laranja para fragmentar R$ 3.000 em 8 PIX de R$ 375. A regra detecta: valores R$100-500 + alta velocidade = 97.2% de fraude nesta faixa.', '{}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Score ML Alto + Canal Risco', 'risk_score > 0.7 AND channel == PIX', 'review', true, '[{"field": "risk_score", "value": "0.7", "operator": ">"}, {"field": "channel", "value": "PIX", "operator": "=="}]'::jsonb, 'AND', 9, 'SITUAÇÃO HIPOTÉTICA: Sistema de ML detecta padrão anormal: transferência para chave aleatória + horário incomum. Score 85% + PIX = dupla confirmação de risco.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Horário Noturno 21h + Valor Médio', 'hour >= 21 AND hour <= 23 AND amount >= 1000 AND amount <= 5000', 'review', true, '[{"field": "hour", "value": "21", "operator": ">="}, {"field": "hour", "value": "23", "operator": "<="}, {"field": "amount", "value": "1000", "operator": ">="}, {"field": "amount", "value": "5000", "operator": "<="}]'::jsonb, 'AND', 10, 'SITUAÇÃO HIPOTÉTICA: Lucia recebe link de promoção às 22h via WhatsApp. Acessa site falso e faz PIX de R$ 2.800 para "garantir o prêmio". A regra detecta: horário 21-23h tem 95.65% de fraude.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Conta Nova + PIX', 'account_age_days < 30 AND channel == PIX AND amount > 1000', 'review', true, '[{"field": "account_age_days", "value": "30", "operator": "<"}, {"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "1000", "operator": ">"}]'::jsonb, 'AND', 11, 'SITUAÇÃO HIPOTÉTICA: Fraudador abre conta com documentos falsos há 15 dias. Tenta transferir R$ 4.000 para conta de terceiros. A regra detecta: conta nova + PIX = padrão de lavagem.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Chave PIX Aleatória + Alto Valor', 'pix_key_type == ALEATORIA AND amount > 3000', 'review', true, '[{"field": "pix_key_type", "value": "ALEATORIA", "operator": "=="}, {"field": "amount", "value": "3000", "operator": ">"}]'::jsonb, 'AND', 12, 'SITUAÇÃO HIPOTÉTICA: Roberto recebe pedido de PIX para chave aleatória de "fornecedor". Valor: R$ 15.000. A regra alerta: chaves aleatórias são usadas em 68% das fraudes para dificultar rastreamento.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('Valor Limite BACEN Dia', 'amount_24h > 20000', 'alert', true, '[{"field": "amount_24h", "value": "20000", "operator": ">"}]'::jsonb, 'AND', 13, 'SITUAÇÃO HIPOTÉTICA: Empresa pequena faz vários PIX totalizando R$ 25.000/dia. A regra alerta para verificação: pode ser operação legítima ou fragmentação para evitar limites BACEN.', '{}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('TED/BOLETO Alta Quantia', 'channel in TED,BOLETO AND amount > 20000', 'review', true, '[{"field": "channel", "value": "TED,BOLETO", "operator": "in"}, {"field": "amount", "value": "20000", "operator": ">"}]'::jsonb, 'AND', 14, 'SITUAÇÃO HIPOTÉTICA: Empresa recebe boleto falso de "fornecedor" por e-mail. Valor: R$ 45.000. A regra envia para revisão: embora TED/BOLETO tenham 16% de fraude, valores altos requerem validação.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CREDITO - Compra Internacional Alto Valor', 'type == CARTAO_CREDITO AND amount > 5000 AND location contains INTERNACIONAL', 'review', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "amount", "value": "5000", "operator": ">"}, {"field": "location", "value": "INTERNACIONAL", "operator": "contains"}]'::jsonb, 'AND', 1, 'SITUAÇÃO HIPOTÉTICA: Cartão de Roberto é clonado em site de phishing. Criminosos fazem compra de US$ 2.000 em loja online da China. A regra intercepta: compra internacional + alto valor = padrão de cl', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
