 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CREDITO - Primeiro Uso Online Alto Valor', 'type == CARTAO_CREDITO AND is_first_transaction == true AND amount > 2000', 'step_up', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "is_first_transaction", "value": "true", "operator": "=="}, {"field": "amount", "value": "2000", "operator": ">"}]'::jsonb, 'AND', 4, 'SITUAÇÃO HIPOTÉTICA: Cartão recém-emitido tenta primeira compra online de R$ 4.000. Pode ser fraudador que obteve dados do cartão antes do cliente usar.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
