 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX - Agendado Alto Valor', 'channel == PIX AND is_scheduled == true AND amount > 10000', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "is_scheduled", "value": "true", "operator": "=="}, {"field": "amount", "value": "10000", "operator": ">"}]'::jsonb, 'AND', 11, 'SITUAÇÃO HIPOTÉTICA: PIX agendado de R$ 15.000 para próxima semana. Criminoso pode ter agendado para dar tempo de fugir antes do débito.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
