 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX - Limite Noturno Bancário', 'channel == PIX AND hour >= 20 AND amount > 1000', 'step_up', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "hour", "value": "20", "operator": ">="}, {"field": "amount", "value": "1000", "operator": ">"}]'::jsonb, 'AND', 13, 'SITUAÇÃO HIPOTÉTICA: PIX de R$ 2.500 às 21h30. Conforme regulação BACEN, PIX noturno acima de R$ 1.000 requer validação extra.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX - Score ML Crítico', 'channel == PIX AND risk_score > 0.85', 'block', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "risk_score", "value": "0.85", "operator": ">"}]'::jsonb, 'AND', 14, 'SITUAÇÃO HIPOTÉTICA: Modelo de ML indica 90% de probabilidade de fraude. Bloquear imediatamente para investigação.', '{}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX - Telefone Celular Pré-pago', 'channel == PIX AND pix_key_type == TELEFONE AND amount > 2000', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "pix_key_type", "value": "TELEFONE", "operator": "=="}, {"field": "amount", "value": "2000", "operator": ">"}]'::jsonb, 'AND', 15, 'SITUAÇÃO HIPOTÉTICA: PIX de R$ 3.000 para número de telefone. Fraudadores usam chips descartáveis para receber valores.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX - Final de Semana + Alto Valor', 'channel == PIX AND day_of_week in 5,6 AND amount > 5000', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "day_of_week", "value": "5,6", "operator": "in"}, {"field": "amount", "value": "5000", "operator": ">"}]'::jsonb, 'AND', 16, 'SITUAÇÃO HIPOTÉTICA: PIX de R$ 8.000 no sábado. Fraudadores preferem finais de semana quando há menos fiscalização bancária.', '{}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('VALOR - Micro Transação Suspeita', 'amount < 10 AND velocity_1h > 10', 'alert', true, '[{"field": "amount", "value": "10", "operator": "<"}, {"field": "velocity_1h", "value": "10", "operator": ">"}]'::jsonb, 'AND', 1, 'SITUAÇÃO: Criminoso testa cartão com múltiplas compras de R$1-5 para verificar se está ativo antes de fazer compra grande.', '{}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
