 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('VELOCITY - Daily Limit Structuring', 'amount_24h > 9000 AND amount_24h < 10000 AND velocity_24h > 3', 'review', true, '[{"field": "amount_24h", "value": "9000", "operator": ">"}, {"field": "amount_24h", "value": "10000", "operator": "<"}, {"field": "velocity_24h", "value": "3", "operator": ">"}]'::jsonb, 'AND', 132, 'AML: Múltiplas transações logo abaixo de R$10k = estruturação para evadir COAF.', '{"fraud_type": "STRUCTURING"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('VELOCITY - Failed Auth Attempts', 'velocity_1h > 5 AND status == REJECTED', 'block', true, '[{"field": "velocity_1h", "value": "5", "operator": ">"}, {"field": "status", "value": "REJECTED", "operator": "=="}]'::jsonb, 'AND', 133, 'FRAUD: 5+ tentativas rejeitadas em 1h = ataque de força bruta ou cartão roubado.', '{"fraud_type": "BRUTE_FORCE"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('VELOCITY - Weekend Night Burst', 'day_of_week in 0,6 AND hour >= 22 AND velocity_1h > 3', 'block', true, '[{"field": "day_of_week", "value": "0,6", "operator": "in"}, {"field": "hour", "value": "22", "operator": ">="}, {"field": "velocity_1h", "value": "3", "operator": ">"}]'::jsonb, 'AND', 134, 'BIOCATCH: Fim de semana + noite + alta velocidade = período de menor vigilância bancária.', '{"fraud_type": "WEEKEND_ATTACK"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('ML_PATTERN - Anomalia de Valor', 'risk_score > 0.6 AND amount > 3000', 'review', true, '[{"field": "risk_score", "value": "0.6", "operator": ">"}, {"field": "amount", "value": "3000", "operator": ">"}]'::jsonb, 'AND', 135, 'ML 2024: XGBoost detectou padrão anômalo + valor alto = alta probabilidade fraude.', '{"fraud_type": "ML_ANOMALY"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('ML_PATTERN - Behavioral Deviation', 'risk_score > 0.5 AND is_first_transaction == false AND velocity_24h > 5', 'review', true, '[{"field": "risk_score", "value": "0.5", "operator": ">"}, {"field": "is_first_transaction", "value": "false", "operator": "=="}, {"field": "velocity_24h", "value": "5", "operator": ">"}]'::jsonb, 'AND', 136, 'ML 2024: Desvio comportamental detectado. Cliente normal não faz 5+ transações/dia.', '{"fraud_type": "BEHAVIORAL_ANOMALY"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
