 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('GEO - Timezone Inconsistente', 'is_new_device == true AND hour >= 2 AND hour <= 5 AND location != HABITUAL', 'block', true, '[{"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "hour", "value": "2", "operator": ">="}, {"field": "hour", "value": "5", "operator": "<="}, {"field": "location", "value": "HABITUAL", "operator": "!="}]'::jsonb, 'AND', 141, 'GEO: Timezone do device não bate com localização declarada. Uso de VPN.', '{"fraud_type": "TIMEZONE_SPOOF"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
