 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('MULTI_FACTOR - Quádrupla Verificação', 'risk_score > 0.5 AND is_new_device == true AND velocity_1h > 2 AND amount > 1000', 'block', true, '[{"field": "risk_score", "value": "0.5", "operator": ">"}, {"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "velocity_1h", "value": "2", "operator": ">"}, {"field": "amount", "value": "1000", "operator": ">"}]'::jsonb, 'AND', 154, 'MULTI: ML score + Novo device + Alta velocidade + Valor alto = fraude confirmada.', '{"fraud_type": "MULTI_FACTOR"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('MULTI_FACTOR - Perfil Conta Laranja Completo', 'account_age_days < 30 AND velocity_24h > 10 AND amount_24h > 10000 AND pix_key_type in ALEATORIA,TELEFONE', 'block', true, '[{"field": "account_age_days", "value": "30", "operator": "<"}, {"field": "velocity_24h", "value": "10", "operator": ">"}, {"field": "amount_24h", "value": "10000", "operator": ">"}, {"field": "pix_key_type", "value": "ALEATORIA,TELEFONE", "operator": "in"}]'::jsonb, 'AND', 155, 'FEBRABAN: Perfil completo de conta laranja detectado. Bloqueio imediato.', '{"fraud_type": "CONTA_LARANJA_CONFIRMADA"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
