 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DEBITO - Contactless Limite', 'type == CARTAO_DEBITO AND channel == CONTACTLESS AND amount > 200', 'step_up', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "channel", "value": "CONTACTLESS", "operator": "=="}, {"field": "amount", "value": "200", "operator": ">"}]'::jsonb, 'AND', 158, 'VISA/MASTERCARD: Pagamento por aproximação > R$200 exige senha.', '{"regulation": "BANDEIRAS"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DEBITO - Saque Internacional', 'type == CARTAO_DEBITO AND channel == ATM AND location contains INTERNACIONAL', 'review', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "channel", "value": "ATM", "operator": "=="}, {"field": "location", "value": "INTERNACIONAL", "operator": "contains"}]'::jsonb, 'AND', 159, 'INTERNATIONAL: Saque em ATM no exterior. Verificar se cliente viajou.', '{"fraud_type": "INTERNATIONAL_ATM"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CARTAO_NOVO - Débito Recém-Emitido Alto Valor', 'type == CARTAO_DEBITO AND account_age_days < 7 AND amount > 500', 'review', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "account_age_days", "value": "7", "operator": "<"}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 200, 'CENÁRIO: Cartão de débito emitido há menos de 7 dias fazendo compra acima de R$500. Fraudadores ativam cartões roubados rapidamente antes do titular perceber.', '{"source": "SCENARIOS_DEBITO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CARTAO_NOVO - Crédito Recém-Emitido + VPN', 'type == CARTAO_CREDITO AND account_age_days < 14 AND ip_address contains VPN', 'block', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "account_age_days", "value": "14", "operator": "<"}, {"field": "ip_address", "value": "VPN", "operator": "contains"}]'::jsonb, 'AND', 201, 'CENÁRIO: Cartão de crédito novo + VPN = alta probabilidade de uso fraudulento. Criminoso mascara localização para testar cartão roubado.', '{"source": "SCENARIOS_CREDITO"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CARTAO_NOVO - Primeira Transação Noturna', 'account_age_days < 7 AND hour >= 22 AND amount > 200', 'review', true, '[{"field": "account_age_days", "value": "7", "operator": "<"}, {"field": "hour", "value": "22", "operator": ">="}, {"field": "amount", "value": "200", "operator": ">"}]'::jsonb, 'AND', 202, 'CENÁRIO: Cartão emitido há poucos dias + primeira transação de madrugada = padrão de teste de cartão clonado.', '{"source": "SCENARIOS_DEBITO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('ENDERECO - Entrega Diferente do Faturamento', 'channel == ECOMMERCE AND location != HABITUAL AND amount > 300', 'step_up', true, '[{"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "location", "value": "HABITUAL", "operator": "!="}, {"field": "amount", "value": "300", "operator": ">"}]'::jsonb, 'AND', 203, 'CENÁRIO: Compra online com entrega em endereço diferente do cadastrado. Fraudador redireciona produto para endereço de laranja.', '{"source": "SCENARIOS_CREDITO"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('ENDERECO - Mismatch + Alto Valor', 'channel == ECOMMERCE AND is_new_device == true AND location != HABITUAL AND amount > 1000', 'block', true, '[{"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "location", "value": "HABITUAL", "operator": "!="}, {"field": "amount", "value": "1000", "operator": ">"}]'::jsonb, 'AND', 204, 'CENÁRIO: Novo dispositivo + endereço diferente + valor alto = tripla confirmação de fraude. Compra de R$2.000 em eletrônicos enviada para outro estado.', '{"source": "SCENARIOS_CREDITO"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('TRIANGULACAO - Vendedor Intermediário', 'channel == ECOMMERCE AND velocity_24h > 5 AND amount >= 200 AND amount <= 2000', 'review', true, '[{"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "velocity_24h", "value": "5", "operator": ">"}, {"field": "amount", "value": "200", "operator": ">="}, {"field": "amount", "value": "2000", "operator": "<="}]'::jsonb, 'AND', 205, 'CENÁRIO TRIANGULAÇÃO: Vendedor compra produtos com cartão roubado e revende. Múltiplas compras de valores médios para produtos de fácil revenda.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "TRIANGULACAO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('TRIANGULACAO - Compra + Reenvio', 'channel == ECOMMERCE AND type == CARTAO_CREDITO AND velocity_1h > 2 AND amount > 500', 'review', true, '[{"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "velocity_1h", "value": "2", "operator": ">"}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 206, 'CENÁRIO TRIANGULAÇÃO: Fraudador compra produto de varejista legítimo e envia para comprador que pagou em site falso. Padrão: múltiplas compras rápidas.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "TRIANGULACAO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DADOS_INCONSISTENTES - CPF vs Titular', 'cpf != TITULAR AND amount > 500', 'review', true, '[{"field": "cpf", "value": "TITULAR", "operator": "!="}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 207, 'CENÁRIO: Dados do pagador não correspondem ao titular do cartão. Nome ou CPF diferente = provável uso de documento falso ou cartão roubado.', '{"source": "SCENARIOS_DEBITO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DADOS_INCONSISTENTES - Beneficiário Suspeito', 'channel == PIX AND cpf != TITULAR AND pix_key_type == CPF', 'alert', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "cpf", "value": "TITULAR", "operator": "!="}, {"field": "pix_key_type", "value": "CPF", "operator": "=="}]'::jsonb, 'AND', 208, 'CENÁRIO: PIX para CPF diferente do titular pode indicar transferência para conta laranja ou vítima de golpe.', '{"source": "SCENARIOS_PIX"}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DEBITO_MAQUININHA - Adulterada Valor Alto', 'type == CARTAO_DEBITO AND channel == POS AND amount > 500 AND velocity_1h > 2', 'review', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "channel", "value": "POS", "operator": "=="}, {"field": "amount", "value": "500", "operator": ">"}, {"field": "velocity_1h", "value": "2", "operator": ">"}]'::jsonb, 'AND', 209, 'CENÁRIO MAQUININHA ADULTERADA: Criminoso troca maquininha em estabelecimento. Múltiplas transações POS de valores altos em curto período = clonagem em massa.', '{"source": "SCENARIOS_DEBITO", "fraud_type": "MAQUININHA_ADULTERADA"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DEBITO_MAQUININHA - Mesmo Terminal Muitos Cartões', 'type == CARTAO_DEBITO AND channel == POS AND velocity_1h > 5', 'block', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "channel", "value": "POS", "operator": "=="}, {"field": "velocity_1h", "value": "5", "operator": ">"}]'::jsonb, 'AND', 210, 'CENÁRIO MAQUININHA ADULTERADA: 5+ cartões diferentes passando no mesmo terminal em 1 hora = maquininha comprometida capturando dados.', '{"source": "SCENARIOS_DEBITO", "fraud_type": "MAQUININHA_ADULTERADA"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('DEBITO_NAO_RECONHECIDA - Transação Atípica', 'type == CARTAO_DEBITO AND is_new_device == true AND hour >= 1 AND hour <= 5', 'review', true, '[{"field": "type", "value": "CARTAO_DEBITO", "operator": "=="}, {"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "hour", "value": "1", "operator": ">="}, {"field": "hour", "value": "5", "operator": "<="}]'::jsonb, 'AND', 211, 'CENÁRIO TRANSAÇÃO NÃO RECONHECIDA: Débito de madrugada em dispositivo novo. Cliente provavelmente não autorizou - cartão pode ter sido clonado.', '{"source": "SCENARIOS_DEBITO", "fraud_type": "NAO_RECONHECIDA"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CREDITO_APP_PAGAMENTO - Fraude App Terceiro', 'type == CARTAO_CREDITO AND channel == APP_TERCEIRO AND amount > 500', 'review', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "channel", "value": "APP_TERCEIRO", "operator": "=="}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 212, 'CENÁRIO FRAUDE APP PAGAMENTO: Cartão cadastrado em app fraudulento ou wallet comprometida. Compra de R$800 via app de pagamento suspeito.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "APP_PAGAMENTO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CREDITO_CHARGEBACK - Padrão de Estorno', 'type == CARTAO_CREDITO AND channel == ECOMMERCE AND amount >= 500 AND amount <= 3000', 'alert', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "amount", "value": "500", "operator": ">="}, {"field": "amount", "value": "3000", "operator": "<="}]'::jsonb, 'AND', 213, 'CENÁRIO FRAUDE DE ESTORNO: Cliente compra, recebe produto e depois contesta cobrança alegando não reconhecer. Faixa R$500-3.000 é típica.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "CHARGEBACK"}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CREDITO_SEM_3DS - Compra Sem Autenticação', 'type == CARTAO_CREDITO AND channel == ECOMMERCE AND amount > 1000 AND is_new_device == true', 'step_up', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "channel", "value": "ECOMMERCE", "operator": "=="}, {"field": "amount", "value": "1000", "operator": ">"}, {"field": "is_new_device", "value": "true", "operator": "=="}]'::jsonb, 'AND', 214, 'CENÁRIO COMPRA SEM 3D SECURE: Loja sem autenticação 3DS + dispositivo novo + valor alto = alto risco. Exigir validação adicional.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "SEM_3DS"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX_FALSO_COMPROVANTE - Comprovante Adulterado', 'channel == PIX AND pix_key_type == ALEATORIA AND amount >= 100 AND amount <= 500', 'alert', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "pix_key_type", "value": "ALEATORIA", "operator": "=="}, {"field": "amount", "value": "100", "operator": ">="}, {"field": "amount", "value": "500", "operator": "<="}]'::jsonb, 'AND', 215, 'CENÁRIO FALSO COMPROVANTE: Golpista envia comprovante editado no Photoshop para vendedor liberar produto sem esperar confirmação do banco.', '{"source": "SCENARIOS_PIX", "fraud_type": "FALSO_COMPROVANTE"}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX_ERRO_CHAVE - Indução ao Erro', 'channel == PIX AND pix_key_type in CPF,TELEFONE AND velocity_1h > 1 AND amount < 1000', 'alert', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "pix_key_type", "value": "CPF,TELEFONE", "operator": "in"}, {"field": "velocity_1h", "value": "1", "operator": ">"}, {"field": "amount", "value": "1000", "operator": "<"}]'::jsonb, 'AND', 216, 'CENÁRIO ERRO DE CHAVE: Golpista convence vítima a transferir para chave errada alegando teste ou correção. Múltiplas transferências pequenas.', '{"source": "SCENARIOS_PIX", "fraud_type": "ERRO_CHAVE"}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX_FALSO_SUPORTE - Suporte Técnico Falso', 'channel == PIX AND is_new_device == true AND velocity_1h > 2 AND amount > 500', 'block', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "is_new_device", "value": "true", "operator": "=="}, {"field": "velocity_1h", "value": "2", "operator": ">"}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 217, 'CENÁRIO FALSO SUPORTE TÉCNICO: Criminoso liga fingindo ser do banco pedindo PIX para "regularizar conta". Novo device + múltiplos PIX = controle remoto.', '{"source": "SCENARIOS_PIX", "fraud_type": "FALSO_SUPORTE"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('COMBO - Login Falho + Transação Rápida', 'velocity_1h > 3 AND amount > 200 AND is_new_device == true', 'block', true, '[{"field": "velocity_1h", "value": "3", "operator": ">"}, {"field": "amount", "value": "200", "operator": ">"}, {"field": "is_new_device", "value": "true", "operator": "=="}]'::jsonb, 'AND', 218, 'CENÁRIO DOS ARQUIVOS: Muitas tentativas + transações rápidas + device novo = conta comprometida ou ataque de força bruta.', '{"source": "SCENARIOS_COMBINED"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('COMBO - VPN + Horário Atípico + Valor', 'ip_address contains VPN AND hour >= 1 AND hour <= 5 AND amount > 500', 'block', true, '[{"field": "ip_address", "value": "VPN", "operator": "contains"}, {"field": "hour", "value": "1", "operator": ">="}, {"field": "hour", "value": "5", "operator": "<="}, {"field": "amount", "value": "500", "operator": ">"}]'::jsonb, 'AND', 219, 'CENÁRIO DOS ARQUIVOS: VPN + madrugada + valor significativo = tripla confirmação de fraude. Criminoso oculta localização em horário de baixa vigilância.', '{"source": "SCENARIOS_COMBINED"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('COMBO - Comportamento Incomum + Alto Valor', 'is_first_transaction == false AND amount > 5000 AND velocity_24h > 3', 'review', true, '[{"field": "is_first_transaction", "value": "false", "operator": "=="}, {"field": "amount", "value": "5000", "operator": ">"}, {"field": "velocity_24h", "value": "3", "operator": ">"}]'::jsonb, 'AND', 220, 'CENÁRIO DOS ARQUIVOS: Cliente habitual com comportamento atípico - valor muito acima do padrão + múltiplas transações = possível comprometimento.', '{"source": "SCENARIOS_COMBINED"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('COMBO - Beneficiário Novo + Valor Alto', 'channel == PIX AND pix_key_type in ALEATORIA,CPF AND amount > 2000 AND velocity_24h < 3', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "pix_key_type", "value": "ALEATORIA,CPF", "operator": "in"}, {"field": "amount", "value": "2000", "operator": ">"}, {"field": "velocity_24h", "value": "3", "operator": "<"}]'::jsonb, 'AND', 221, 'CENÁRIO DOS ARQUIVOS: PIX para beneficiário nunca antes usado + valor alto = possível golpe de engenharia social.', '{"source": "SCENARIOS_COMBINED"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CARDING - Teste de Cartão Pequeno Valor', 'type == CARTAO_CREDITO AND amount < 10 AND velocity_1h > 5', 'block', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "amount", "value": "10", "operator": "<"}, {"field": "velocity_1h", "value": "5", "operator": ">"}]'::jsonb, 'AND', 222, 'CENÁRIO CARDING: Fraudador testa cartões com compras < R$10 para verificar se estão ativos. 5+ testes em 1h = ataque automatizado.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "CARDING"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('CARDING - BIN Attack', 'type == CARTAO_CREDITO AND velocity_1h > 10 AND amount < 50', 'block', true, '[{"field": "type", "value": "CARTAO_CREDITO", "operator": "=="}, {"field": "velocity_1h", "value": "10", "operator": ">"}, {"field": "amount", "value": "50", "operator": "<"}]'::jsonb, 'AND', 223, 'CENÁRIO BIN ATTACK: 10+ tentativas por hora com valores baixos = ataque de geração de números válidos via Luhn algorithm.', '{"source": "SCENARIOS_CREDITO", "fraud_type": "BIN_ATTACK"}'::jsonb, 'blocking') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX_AGENDADO - Falso com Pressão', 'channel == PIX AND is_scheduled == true AND amount > 5000 AND pix_key_type == ALEATORIA', 'review', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "is_scheduled", "value": "true", "operator": "=="}, {"field": "amount", "value": "5000", "operator": ">"}, {"field": "pix_key_type", "value": "ALEATORIA", "operator": "=="}]'::jsonb, 'AND', 224, 'CENÁRIO PIX AGENDADO FALSO: Golpista agenda PIX alto para chave aleatória. Quando vítima percebe, dinheiro já foi dispersado.', '{"source": "SCENARIOS_PIX", "fraud_type": "PIX_AGENDADO_FALSO"}'::jsonb, 'routing') ON CONFLICT DO NOTHING;
 INSERT INTO hard_rules (name, condition, action, enabled, conditions_json, logic_operator, priority, description, action_config, rule_type) VALUES ('PIX_ANUNCIO_FALSO - Marketplace Fraudulento', 'channel == PIX AND amount >= 300 AND amount <= 3000 AND pix_key_type in ALEATORIA,CNPJ', 'alert', true, '[{"field": "channel", "value": "PIX", "operator": "=="}, {"field": "amount", "value": "300", "operator": ">="}, {"field": "amount", "value": "3000", "operator": "<="}, {"field": "pix_key_type", "value": "ALEATORIA,CNPJ", "operator": "in"}]'::jsonb, 'AND', 225, 'CENÁRIO ANÚNCIO FALSO: Golpista posta produto em marketplace com preço baixo. Vítima faz PIX e produto nunca chega. Faixa R$300-3k é típica.', '{"source": "SCENARIOS_PIX", "fraud_type": "ANUNCIO_FALSO"}'::jsonb, 'alerting') ON CONFLICT DO NOTHING;
